def test_governed_package_inspection_records_only_narrow_relation(db_session,board,related):
    from tests.test_organization_rea_compilation import correlated_inspect
    from app.services import organization_rea_build as build
    from app.models.domain import AuditLog
    from sqlmodel import select
    result=correlated_inspect(db_session,board,related)
    assert result['candidate_to_ci_source_relation_verified'] is True
    assert result['committed_recipe_bytes_match_review'] is True
    for key in ('independent_compiler_causality_verified','source_to_build_verified','publisher_verified','runtime_closure_verified','provider_ready','execution_authorized','live_transport_owned','isolation_verified'):
        assert result[key] is False
    proof=json.loads(db_session.exec(select(AuditLog).where(AuditLog.action==build.ACTION)).one().after_state_json)['ci_attestation']
    assert proof['owning_github_execution_authenticated'] is False
    assert 'objects' not in proof['source_relation'] and str(related['witness_path']) not in json.dumps(proof)


def test_witness_changed_after_audit_rolls_back(db_session,board,related,monkeypatch):
    from tests.test_organization_rea_compilation import correlated_inspect
    from tests.test_organization_rea_build import assert_no_audit
    from app.services import organization_rea_build as build
    original=build.record_audit
    def mutate(*args,**kwargs):
        result=original(*args,**kwargs)
        path=related['witness_path'];path.chmod(0o644);path.write_bytes(path.read_bytes()+b' ');path.chmod(0o444)
        return result
    monkeypatch.setattr(build,'record_audit',mutate)
    with pytest.raises(InvalidTransition):correlated_inspect(db_session,board,related)
    assert_no_audit(db_session)


@pytest.mark.parametrize('mutation',['reversed-parents','one-parent','extra-parent','different-tree'])
def test_rehashed_source_commit_cannot_change_approved_topology(mutation):
    raw,args,objects,encode=witness()
    old=args['ci_source_sha'];item=objects.pop(old)
    data=base64.b64decode(item['data_base64'])
    candidate=args['candidate_sha']
    original=('parent '+'c'*40+'\nparent '+candidate+'\n').encode()
    if mutation=='reversed-parents':changed=('parent '+candidate+'\nparent '+'c'*40+'\n').encode()
    elif mutation=='one-parent':changed=('parent '+candidate+'\n').encode()
    elif mutation=='extra-parent':changed=original+('parent '+'d'*40+'\n').encode()
    else:
        changed=original
        data=b'tree '+b'e'*40+data[45:]
    data=data.replace(original,changed)
    new=relation.object_sha('commit',data)
    objects[new]={'type':'commit','data_base64':base64.b64encode(data).decode()}
    args.update(ci_source_sha=new,ci_workflow_sha=new)
    raw=encode();args['pins']=replace(args['pins'],witness_sha256=ci.sha(raw))
    with pytest.raises(InvalidTransition):relation.verify(raw,**args)
